const D = { scale:1, energy:.65, hue:120, speed:1, density:.5, x:.46, y:.6, pose:'perch', style:'field', act:'bask', seed:0, chub:.5, tail:.5, throat:.5 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
