// pose posture
const perch=P.pose==='perch'?1:0, stalk=P.pose==='stalk'?1:0, display=P.pose==='display'?1:0;
// act — multi-minute skin-mood dramaturgy
let moodDrift, moodSat, creep;
if(P.act==='hunt'){ moodDrift=8*Math.sin(K.t*0.05); moodSat=1.08; creep=1; }
else if(P.act==='threat'){ moodDrift=90*ez(Math.sin(K.t*0.09)*.5+.5); moodSat=1.25; creep=.2; } // flush toward warning colors
else { moodDrift=26*Math.sin(K.t*0.045) + 12*Math.sin(K.t*0.11); moodSat=1.0; creep=.35; } // bask: lazy hue wander

// literal skin hue (P.hue) + slow living shimmer + act mood + display flush
const skinHue = md(H + moodDrift + display*70, 360);
const satBase = clp((48 + display*26)*moodSat, 20, 96);

// characteristic chameleon rock — whole body sways like a leaf
const rock = Math.sin(K.t*2.1*P.speed + K.swell*.6)*(.5+.5*en);
const rrot = rock*0.12 + Math.sin(K.t*0.9*P.speed)*0.03*en;
const rx = rock*22*sc + (stalk?Math.sin(bt*Math.PI)*8*sc:0);
const creepY = -Math.abs(Math.sin(bt*Math.PI*0.5))*creep*6*sc*stalk;
const throb = (0.5+0.5*Math.sin(K.t*3.2 + K.pulse*2)); // gular pump
const kick=K.pulse*.5 + A.bass*.9;

// tongue zap — clk sawtooth every 8 beats (baseline) + bass boost
const zp=frc((bt)/8), win=0.13; let ext=0;
if(zp<win){ ext=Math.sin((zp/win)*Math.PI); }
ext=clp(ext + clp(A.bass*1.8-0.6,0,1), 0, 1.15);

const cx=P.x*width, ay=P.y*height;
const s=sc;

// fly target drifts
const flyX=cx + (140+30*Math.sin(K.t*0.7))*s, flyY=ay-(150+40*Math.cos(K.t*0.5))*s;

function skinFill(depth, hoff){
  const hh=md(skinHue+(hoff||0)+(iri?depth*70:0),360);
  if(blueprint){ noFill(); stroke(md(H+180,360),16,96,82); strokeWeight(1.3*s); strokeJoin(ROUND); return; }
  if(xray){ noStroke(); fill(md(H,360),38,64,12); return; }
  if(stipple){ noStroke(); fill(md(hh,360), satBase*.7, 26+depth*44); return; }
  if(iri){ noStroke(); fill(md(hh,360), clp(satBase*.9,20,90), 38+depth*46); return; }
  noStroke(); fill(md(hh,360), clp(satBase+(1-depth)*18,20,96), 26+depth*52);
}
function stip(cx0,cy0,rw,rh,depth,base){ if(!stipple)return; const n=Math.floor(base*(0.5+P.density)); noStroke();
  for(let i=0;i<n;i++){ const a=fr(i*3.1+cx0)*TAU, rr=Math.sqrt(fr(i*5.7+cy0)); const px=cx0+Math.cos(a)*rw*rr, py=cy0+Math.sin(a)*rh*rr;
    fill(md(skinHue+(fr(i*7.3)-.5)*40,360), satBase, 30+fr(i*2.9)*60, 70); circle(px,py,(0.8+fr(i*9.1)*1.6)*s); } }

// ===== BRANCH (behind, fixed) =====
push(); noStroke();
const bA=0.32; // branch angle
fill(md(H+ (blueprint?180:20),360), blueprint?10:24, blueprint?80:34);
push(); translate(cx, ay+8*s); rotate(bA);
if(blueprint){ noFill(); stroke(md(H+180,360),12,80,60); strokeWeight(1.2*s); }
rectMode(CENTER); rect(0,0,320*s,26*s*CH, 12*s); rectMode(CORNER);
// a couple of leaves
