pop(); pop();

// ===== BODY GROUP (rocks) =====
push();
translate(cx+rx, ay-90*s+creepY);
rotate(rrot);

// ---- TAIL (curling spiral, behind) ----
const curl=(0.45+0.45*Math.sin(K.t*0.35*P.speed))*(0.7+P.tail*.6) + display*0.2;
const segs=16; const tp=[{x:-60*CH*s,y:-6*s}]; let ang=Math.PI*0.35;
for(let i=1;i<segs;i++){ const step=(9- i*0.18)*s*(0.7+P.tail*0.4); ang += (0.18 + i*0.05*curl); tp.push({x:tp[i-1].x-Math.cos(ang)*step, y:tp[i-1].y+Math.sin(ang)*step}); }
function ribbon(pts,w0,w1){ beginShape();
  for(let i=0;i<pts.length;i++){ const t=i/(pts.length-1), w=(w0*(1-t)+w1*t); const p=pts[i],q=pts[Math.min(i+1,pts.length-1)]; const dx=q.x-p.x,dy=q.y-p.y,L=Math.hypot(dx,dy)||1; vertex(p.x-dy/L*w, p.y+dx/L*w);}
  for(let i=pts.length-1;i>=0;i--){ const t=i/(pts.length-1), w=(w0*(1-t)+w1*t); const p=pts[i],q=pts[Math.min(i+1,pts.length-1)]; const dx=q.x-p.x,dy=q.y-p.y,L=Math.hypot(dx,dy)||1; vertex(p.x+dy/L*w, p.y-dx/L*w);}
  endShape(CLOSE); }
skinFill(.3); ribbon(tp, 13*s*TL, 1.6*s);
if(stipple) for(let i=0;i<tp.length;i+=2) stip(tp[i].x,tp[i].y, 8*s,8*s,.3,4);

// ---- FAR legs (darker) ----
function limb(hx,hy,fx,fy,depth,grip){ push();
  skinFill(depth); const mx=(hx+fx)/2 - 8*s, my=(hy+fy)/2 + 10*s;
  ribbon([{x:hx,y:hy},{x:mx,y:my},{x:fx,y:fy}], 9*s*CH, 4*s);
  // grip foot (zygodactyl mitten)
  if(!blueprint){ skinFill(depth+.1); ellipse(fx,fy,14*s,10*s); }
  pop(); }
limb(-24*s, 34*s, -40*s, 84*s, .16, 1);
limb(38*s, 30*s, 58*s, 82*s, .18, 1);

// ---- BODY MASS (color field, laterally compressed, tall belly) ----
if(field){ drawingContext.shadowColor='hsba('+skinHue+',70%,70%,0.55)'; drawingContext.shadowBlur=22*s; }
skinFill(.55);
beginShape();
vertex(-64*CH*s,-4*s);
bezierVertex(-70*CH*s,-64*s, -30*s,-92*s, 12*s,-92*s);
bezierVertex(58*s,-92*s, 74*CH*s,-70*s, 82*CH*s,-30*s);
bezierVertex(88*CH*s, 8*s, 70*s, 44*s*(1+.25*throb*TH), 18*s, 50*s*(1+.3*throb*TH));
bezierVertex(-16*s, 54*s, -58*CH*s, 40*s, -64*CH*s,-4*s);
endShape(CLOSE);
if(field){ drawingContext.shadowBlur=0; }
// belly warm color-field wash (field/iri) — luminous underside
if(field||iri){ push(); blendMode(ADD); noStroke(); fill(md(skinHue+40,360),60,70,10); ellipse(6*s,34*s,120*CH*s,48*s); blendMode(BLEND); pop(); }
stip(6*s,-20*s, 78*CH*s,66*s,.5,60);

// ---- DORSAL CREST (sawtooth ridge) ----
push(); skinFill(.7, display?18:6);
if(blueprint){ noFill(); stroke(md(H+180,360),14,96,84); strokeWeight(1.2*s); }
beginShape();
const crestN=11;
for(let i=0;i<=crestN;i++){ const t=i/crestN; const bx=-56*CH*s + t*(120*CH*s); const by=-70*s - 22*s*Math.sin(t*Math.PI) - ((i%2)? (7+display*9)*s : 0); vertex(bx,by); }
for(let i=crestN;i>=0;i--){ const t=i/crestN; const bx=-56*CH*s + t*(120*CH*s); const by=-64*s - 20*s*Math.sin(t*Math.PI); vertex(bx,by); }
endShape(CLOSE); pop();

// ---- NEAR legs ----
limb(-18*s, 30*s, -30*s, 82*s, .42, 1);
limb(44*s, 26*s, 62*s, 80*s, .46, 1);

// ---- HEAD + CASQUE ----
push();
translate(70*CH*s, -66*s);
rotate(-0.05 + kick*0.04 + Math.sin(K.t*0.6)*0.03*en);
// casque helmet
skinFill(.72, 10);
beginShape(); vertex(-6*s,-6*s); bezierVertex(-4*s,-44*s*(1+display*.3), 26*s,-44*s, 30*s,-8*s); vertex(18*s,-2*s); endShape(CLOSE);
// skull + snout
