vertex(-14*s,-8*s); bezierVertex(-14*s,-30*s, 22*s,-30*s, 34*s,-16*s);
vertex(50*s,-6*s); vertex(50*s,8*s); vertex(34*s,14*s);
bezierVertex(20*s,26*s, -12*s,22*s, -14*s,-8*s); endShape(CLOSE);
if(field){ drawingContext.shadowBlur=0; }
stip(12*s,-4*s,28*s,20*s,.6,26);
// mouth line
if(!xray){ stroke(md(skinHue,360),60,14,60); strokeWeight(1.4*s); noFill(); line(48*s,4*s, 30*s,10*s); noStroke(); }
