if(xray){ push(); blendMode(ADD); stroke(md(H+150,360),50,100,80); strokeWeight(1.6*s); noFill();
  drawingContext.shadowColor='hsba('+md(H+150,360)+',60%,100%,0.9)'; drawingContext.shadowBlur=8*s;
