push();
// mouth world position (approx, tracks the rocking body group)
const mx0=cx+rx + (118*CH)*s*Math.cos(rrot) + 66*s*Math.sin(rrot), my0=ay-156*s+creepY;
if(ext>0.02){ const tx=mx0 + (flyX-mx0)*ext, ty=my0 + (flyY-my0)*ext;
  stroke(md(skinHue+20,360),50,96,90); strokeWeight((3.5- ext*1.5)*s); line(mx0,my0, tx,ty);
